"Cline’s Plan mode: it explores, fetches and proposes a plan; file edits are declined, commands still ask.": "Cline의 Plan 모드: 탐색하고 가져온 뒤 계획을 제안합니다. 파일 편집은 거부되고 명령은 여전히 물어봅니다.",
