"Optional reviews, project rules, context search, and worker suggestions.": "선택적 검토, 프로젝트 규칙, 컨텍스트 검색, worker 제안.",
"Optional · selected task evidence is sent to TypeSafe when you run. Provider usage charges apply. PandaCode works without Jev. Advice does not change files, models, or permissions.": "선택 사항 · 실행하면 선택한 작업 증거가 TypeSafe로 전송됩니다. 공급자 사용 요금이 부과됩니다. PandaCode는 Jev 없이도 동작합니다. 조언은 파일, 모델, 권한을 바꾸지 않습니다.",
"Optional, such as us-central1": "선택 사항, 예: us-central1",
"Optional. Leave blank for no token limit.": "선택 사항. 비워 두면 token 한도가 없습니다.",
"Optional. Tone, values and conversational style, kept apart from the instructions. Importing copies the file once; later changes to the file do not change the bot. Personality never grants tools or permissions.": "선택 사항. 어조, 가치관, 대화 스타일로, 지침과는 별도로 관리됩니다. 가져오기는 파일을 한 번만 복사하며, 이후 파일을 바꿔도 Bot은 변하지 않습니다. 성격은 도구나 권한을 절대 부여하지 않습니다.",
