"PandaCode restarts when your agents are done and you step away.": "Agent가 끝나고 자리를 비우면 PandaCode가 재시작합니다.",
"PandaCode runs Linux and macOS VMs on Apple's Virtualization framework: headless, and only the memory you give it.": "PandaCode는 Apple Virtualization 프레임워크에서 Linux와 macOS VM을 실행합니다. 헤드리스이며 할당한 메모리만 사용합니다.",
"PandaCode tools": "PandaCode 도구",
