"PandaCode will restart to update when your agents finish.": "Agent가 끝나면 PandaCode가 재시작하며 업데이트를 완료합니다.",
"PandaCode works without Jev or a TypeSafe key. Optional decision assistance only needs the key for the provider you pick. OpenRouter models are listed only when you open the model menu. Keys are saved privately on this device, outside the keychain. Leave a field empty to keep its saved key.": "PandaCode는 Jev나 TypeSafe 키 없이도 동작합니다. 선택적 의사 결정 지원은 선택한 공급자의 키만 필요로 합니다. OpenRouter 모델은 모델 메뉴를 열 때만 나열됩니다. 키는 이 기기에 키체인 밖에 비공개로 저장됩니다. 필드를 비워 두면 저장된 키가 유지됩니다.",
"PandaCode {0} is available.": "PandaCode {0}이(가) 출시되었습니다.",
