"PandaCode {0} is available. Open GitHub Releases to update this copy.": "PandaCode {0}이(가) 출시되었습니다. 이 사본을 업데이트하려면 GitHub Releases를 여세요.",
"PandaCode {0} is available. Updates for this copy are installed by its package or a new AppImage.": "PandaCode {0}이(가) 출시되었습니다. 이 사본의 업데이트는 패키지 또는 새 AppImage로 설치됩니다.",
