"Reads account limits from your locally configured agent accounts. Requests go directly to the provider or its CLI, never through PandaCode servers. No prompts are sent. Results are cached for one minute; Refresh is limited to once every ten seconds per provider. Some providers do not expose their limits. Usage is shared with other apps using the same account.": "로컬에 구성된 Agent 계정에서 계정 한도를 읽어 옵니다. 요청은 공급자나 그 CLI로 직접 전송되며 PandaCode 서버를 거치지 않습니다. 프롬프트는 전송되지 않습니다. 결과는 1분간 캐시되고, 새로 고침은 공급자별 10초에 한 번으로 제한됩니다. 일부 공급자는 한도를 공개하지 않습니다. 사용량은 같은 계정을 쓰는 다른 앱과 공유됩니다.",
