"Use an account token, or a workspace token with its workspace ID. Agents run the Railway CLI with it (fetched on first use if it is not installed); it never enters their prompts.": "계정 토큰, 또는 워크스페이스 ID가 있는 워크스페이스 토큰을 사용하세요. Agent는 이것으로 Railway CLI를 실행하고(미설치 시 처음 사용할 때 가져옴) 프롬프트에는 절대 들어가지 않습니다.",
