"Uses your AWS CLI sign-in (run `aws login` first). Desktops have no open ports; PandaCode reaches them through Systems Manager, which needs the Session Manager plugin for screens.": "AWS CLI 로그인을 사용합니다 (먼저 `aws login` 실행). 데스크톱은 포트를 열지 않으며, PandaCode는 Systems Manager로 접근합니다. 화면에는 Session Manager 플러그인이 필요합니다.",
"Uses your installed gcloud CLI and its sign-in (run `gcloud auth login` first); PandaCode downloads nothing and stores only the project, region and zone.": "설치된 gcloud CLI와 그 로그인을 사용합니다 (먼저 `gcloud auth login` 실행). PandaCode는 아무것도 내려받지 않고 프로젝트, 리전, 영역만 저장합니다.",
