"Environment variable names use letters, digits and underscores, and do not start with a digit.": "환경 변수 이름은 문자, 숫자, 밑줄을 사용하며 숫자로 시작할 수 없습니다.",
"Every worker must complete or be explicitly abandoned before finishing. Follow up or cancel failed work with a reason.": "마무리 전에 모든 worker가 완료되거나 명시적으로 포기되어야 합니다. 실패한 작업은 후속 조치를 하거나 이유를 들어 취소하세요.",
"File exceeds the 128 KiB preview limit": "파일이 128 KiB 미리 보기 한도를 초과합니다",
"File scopes must be normalized relative paths without wildcards.": "파일 범위는 와일드카드가 없는 정규화된 상대 경로여야 합니다.",
"File search queries must be at most 512 bytes and contain no null characters.": "파일 검색 질의는 최대 512바이트이며 null 문자를 포함할 수 없습니다.",
"Finish Jev assessments before updating an agent.": "Agent를 업데이트하기 전에 Jev 평가를 마치세요.",
"Finish Jev browser tests and setup before updating an agent.": "Agent를 업데이트하기 전에 Jev 브라우저 테스트와 설정을 마치세요.",
"Finish running agents and close terminals before updating an agent.": "Agent를 업데이트하기 전에 실행 중인 Agent를 마치고 터미널을 닫으세요.",
"Form enum constraints conflict": "폼 열거형 제약이 서로 충돌합니다",
"Form enum contains duplicate options": "폼 열거형에 중복 옵션이 있습니다",
"Form enum labels require options": "폼 열거형 레이블에는 옵션이 필요합니다",
"Form numeric constraints conflict": "폼 숫자 제약이 서로 충돌합니다",
"Form required fields are unknown or duplicated": "폼 필수 필드를 알 수 없거나 중복되었습니다",
"Form string length constraints conflict": "폼 문자열 길이 제약이 서로 충돌합니다",
"Forms support at most twenty fields": "폼은 최대 20개의 필드를 지원합니다",
"Forms with arbitrary additional fields are not supported": "임의의 추가 필드가 있는 폼은 지원되지 않습니다",
"Git status exceeds the 1 MiB inspection limit": "Git 상태가 1 MiB 검사 한도를 초과합니다",
"GitHub Copilot CLI does not advertise the selected task mode. Update Copilot CLI, then refresh.": "GitHub Copilot CLI가 선택한 작업 모드를 알리지 않습니다. Copilot CLI를 업데이트한 뒤 새로 고치세요.",
"GitHub Copilot CLI requires sign-in. Run `copilot login` in a terminal, then retry.": "GitHub Copilot CLI에는 로그인이 필요합니다. 터미널에서 `copilot login`을 실행한 뒤 다시 시도하세요.",
"GitHub returned an unexpected repository list.": "GitHub이 예상과 다른 저장소 목록을 반환했습니다.",
"GitHub returned an unexpected sign-in code.": "GitHub이 예상과 다른 로그인 코드를 반환했습니다.",
"Give a bundle identifier such as com.example.App.": "com.example.App 같은 bundle 식별자를 지정하세요.",
"Give an Android package name such as com.example.app.": "com.example.app 같은 Android 패키지 이름을 지정하세요.",
"Give at most one typed answer": "입력형 답변은 최대 하나만 주세요",
"Give the accessibility label to tap.": "탭할 요소의 접근성 레이블을 지정하세요.",
"Give the bot a name.": "Bot에 이름을 지으세요.",
"Give the path of a built .apk for the emulator.": "에뮬레이터용으로 빌드된 .apk 경로를 지정하세요.",
"Give the path of a built .app bundle for the simulator.": "시뮬레이터용으로 빌드된 .app 번들 경로를 지정하세요.",
"Give the pull request a title of up to 256 characters.": "Pull Request 제목은 최대 256자입니다.",
"Give the skill a name in its frontmatter.": "Skill의 frontmatter에 이름을 지정하세요.",
"Goal controls cannot include attachments or skills. Add these in a separate message.": "목표 컨트롤에는 첨부나 Skill을 넣을 수 없습니다. 별도의 메시지로 추가하세요.",
"Goal metadata does not belong to this Codex task.": "목표 메타데이터가 이 Codex 작업에 속하지 않습니다.",
"Goals require the Codex harness.": "목표 기능에는 Codex Agent가 필요합니다.",
"Goals require the Codex harness. The task provider changed before it started.": "목표 기능에는 Codex Agent가 필요합니다. 작업이 시작되기 전에 공급자가 바뀌었습니다.",
"Google Cloud VM names use lowercase letters, digits and dashes, starting with a letter (up to 63).": "Google Cloud VM 이름은 소문자, 숫자, 하이픈을 사용하며 문자로 시작합니다(최대 63자).",
"Grok uses managed update policy. Use its official CLI or ask your administrator to update it.": "Grok는 관리형 업데이트 정책을 사용합니다. 공식 CLI로 업데이트하거나 관리자에게 요청하세요.",
"Grok's release channel is not supported for updates here.": "여기서는 Grok의 릴리스 채널 업데이트를 지원하지 않습니다.",
"Harness state restore was skipped because its archive exceeds the 64 MiB transfer limit.": "Agent 상태 복원이 건너뛰어졌습니다. 아카이브가 64 MiB 전송 한도를 초과합니다.",
"Harness state was skipped because its compressed archive exceeds the 64 MiB transfer limit.": "Agent 상태가 건너뛰어졌습니다. 압축 아카이브가 64 MiB 전송 한도를 초과합니다.",
"Homebrew finished, but rtk was not found afterwards.": "Homebrew는 끝났지만 그 뒤로 rtk를 찾을 수 없습니다.",
"Host tool canceled": "호스트 도구가 취소되었습니다",
"Host tool request does not belong to the active turn": "호스트 도구 요청이 현재 턴에 속하지 않습니다",
"Host tool request is no longer active": "호스트 도구 요청이 더 이상 활성 상태가 아닙니다",
"Host tool timed out": "호스트 도구 시간이 초과되었습니다",
"Host tools are unavailable for this provider": "이 공급자는 호스트 도구를 지원하지 않습니다",
"Host tools are unavailable in this client": "이 클라이언트는 호스트 도구를 지원하지 않습니다",
"Image is no longer available.": "이미지를 더 이상 사용할 수 없습니다.",
"Image response exceeds the supported limits": "이미지 응답이 지원 한도를 초과합니다",
"Images can't be sent to a cloud machine yet.": "이미지는 아직 클라우드 머신으로 보낼 수 없습니다.",
"Images can't be sent to a task on another computer yet.": "이미지는 아직 다른 컴퓨터의 작업으로 보낼 수 없습니다.",
"Import conversations from Claude Code or Codex.": "Claude Code나 Codex에서 대화를 가져오세요.",
"Include Command, Control, Option, or Shift in the shortcut.": "단축키에는 Command, Control, Option 또는 Shift를 포함하세요.",
"InstaBox can't create machines from that image on this account. Pick another one.": "이 계정에서는 그 이미지로 InstaBox 머신을 만들 수 없습니다. 다른 이미지를 고르세요.",
