"Invalid or oversized Codex operation arguments.": "잘못되었거나 지나치게 큰 Codex 작업 인수입니다.",
"Invalid recipe name.": "잘못된 레시피 이름입니다.",
"Invalid screenshot attachment.": "잘못된 스크린샷 첨부입니다.",
"Invalid task stage for a context command.": "컨텍스트 명령에 쓸 수 없는 작업 단계입니다.",
"Invalid team limits or workspace mode.": "잘못된 팀 한도 또는 워크스페이스 모드입니다.",
"Invalid turn change selection.": "잘못된 턴 변경 선택입니다.",
"Jev assistance was disabled or PandaCode is closing. No report was applied.": "Jev 지원이 꺼졌거나 PandaCode가 종료 중입니다. 보고서가 적용되지 않았습니다.",
"Jev choices need 2–24 valid options with descriptions up to 512 bytes.": "Jev 선택지는 설명이 512바이트 이하인 유효한 옵션 2–24개여야 합니다.",
