"Jev decision cancelled.": "Jev 의사 결정이 취소되었습니다.",
"Jev is already being installed.": "Jev가 이미 설치 중입니다.",
"Jev needs nonempty context of at most 32 KiB.": "Jev에는 최대 32 KiB의 비어 있지 않은 컨텍스트가 필요합니다.",
"Jev output exceeded its limit.": "Jev 출력이 한도를 초과했습니다.",
"Jev question identifiers must be unique and valid.": "Jev 질문 식별자는 고유하고 유효해야 합니다.",
"Jev returned an invalid final status.": "Jev가 잘못된 최종 상태를 반환했습니다.",
"Jev returned an invalid runtime event.": "Jev가 잘못된 런타임 이벤트를 반환했습니다.",
"Jev returned an unsupported browser operation.": "Jev가 지원되지 않는 브라우저 작업을 반환했습니다.",
"Jev runtime command failed. Check its installation and Python version.": "Jev 런타임 명령이 실패했습니다. 설치 상태와 Python 버전을 확인하세요.",
"Jev runtime command timed out.": "Jev 런타임 명령 시간이 초과되었습니다.",
"Jev runtime event exceeded its size limit.": "Jev 런타임 이벤트가 크기 한도를 초과했습니다.",
"Jev runtime output exceeded its limit.": "Jev 런타임 출력이 한도를 초과했습니다.",
"Jev stopped without a final report. Check its runtime and API settings.": "Jev가 최종 보고서 없이 멈췄습니다. 런타임과 API 설정을 확인하세요.",
"Jev's combined request is too large. Use fewer or shorter criteria.": "Jev의 통합 요청이 너무 큽니다. 조건을 줄이거나 짧게 하세요.",
"Keep the query within 4,000 characters without null characters.": "질의는 null 문자 없이 4,000자 이내로 하세요.",
"Keyring is locked": "키체인이 잠겨 있습니다",
"Kimi did not return a session ID": "Kimi가 세션 ID를 반환하지 않았습니다",
"Kimi model catalog contains too many models": "Kimi 모델 카탈로그에 모델이 너무 많습니다",
"Kimi model catalog exceeded its output limit": "Kimi 모델 카탈로그가 출력 한도를 초과했습니다",
"Kimi model discovery is unavailable; check the CLI configuration or enter a custom model ID": "Kimi 모델 탐색을 사용할 수 없습니다. CLI 구성을 확인하거나 사용자 지정 모델 ID를 입력하세요",
"Kimi model discovery timed out; enter a custom model ID": "Kimi 모델 탐색 시간이 초과되었습니다. 사용자 지정 모델 ID를 입력하세요",
"Local VMs need a Mac with Apple silicon. Use a cloud sandbox instead.": "로컬 VM에는 Apple silicon Mac이 필요합니다. 대신 클라우드 샌드박스를 사용하세요.",
"Local server discovery exceeded its output limit.": "로컬 서버 탐색이 출력 한도를 초과했습니다.",
"Local server discovery is unavailable. You can still enter a URL.": "로컬 서버 탐색을 사용할 수 없습니다. URL을 직접 입력할 수는 있습니다.",
"Local server discovery requires lsof or, on Linux, ss. You can still enter a URL.": "로컬 서버 탐색에는 lsof가 필요하고(Linux에서는 ss) URL은 직접 입력할 수 있습니다.",
"Local server discovery timed out. Try refreshing.": "로컬 서버 탐색 시간이 초과되었습니다. 새로 고침을 시도하세요.",
"Message and attached context must be under 128 KiB.": "메시지와 첨부 컨텍스트는 합쳐서 128 KiB 미만이어야 합니다.",
"Message must be under 128 KiB.": "메시지는 128 KiB 미만이어야 합니다.",
"Missing process name": "프로세스 이름이 누락되었습니다",
"Missing repo or projectId.": "repo 또는 projectId가 누락되었습니다.",
"Modal refused the token. Check the token ID and secret in Settings → Cloud.": "Modal이 토큰을 거부했습니다. Settings → Cloud에서 토큰 ID와 시크릿을 확인하세요.",
"Modal sandboxes can't be restarted. Create a new one.": "Modal 샌드박스는 재시작할 수 없습니다. 새로 만드세요.",
"Model ID must be 1–200 bytes.": "모델 ID는 1–200바이트여야 합니다.",
"Model ID must be under 200 bytes.": "모델 ID는 200바이트 미만이어야 합니다.",
"Model name is too long.": "모델 이름이 너무 깁니다.",
"More than 5,000 changed files; use Git in the terminal": "변경된 파일이 5,000개를 넘습니다. 터미널에서 Git을 사용하세요",
"Muse Code cancelled the turn": "Muse Code가 턴을 취소했습니다",
"Muse Code closed the session": "Muse Code가 세션을 닫았습니다",
"Muse Code did not return a session ID": "Muse Code가 세션 ID를 반환하지 않았습니다",
"Muse Code did not start a turn": "Muse Code가 턴을 시작하지 않았습니다",
"Muse Code exited before returning models": "Muse Code가 모델을 반환하기 전에 종료되었습니다",
"Muse model catalog exceeded its output limit": "Muse 모델 카탈로그가 출력 한도를 초과했습니다",
"Muse model discovery timed out": "Muse 모델 탐색 시간이 초과되었습니다",
"Native goals cannot run inside an architect team. Use the team controls.": "네이티브 목표는 Architect 팀 안에서 실행할 수 없습니다. 팀 컨트롤을 사용하세요.",
"No VM is running. Start one with vm_manage, or list them with vm_list.": "실행 중인 VM이 없습니다. vm_manage로 시작하거나 vm_list로 나열하세요.",
"No readable text was found in this document. It may be scanned images only.": "이 문서에서 읽을 수 있는 텍스트를 찾지 못했습니다. 스캔 이미지만 있을 수 있습니다.",
"Noninteractive GLM secure-store access is unavailable.": "GLM의 비대화형 보안 저장소 접근을 사용할 수 없습니다.",
"Nothing is waiting for approval.": "승인을 기다리는 항목이 없습니다.",
"Nothing to import at that path.": "그 경로에 가져올 내용이 없습니다.",
"One-click setup is for macOS. Install Android Studio to get the emulator.": "원클릭 설정은 macOS 전용입니다. 에뮬레이터를 쓰려면 Android Studio를 설치하세요.",
"Only HTTP and HTTPS URLs can be opened.": "HTTP와 HTTPS URL만 열 수 있습니다.",
"Only HTTP and HTTPS URLs without embedded credentials can be opened.": "자격 증명이 포함되지 않은 HTTP와 HTTPS URL만 열 수 있습니다.",
"Only HTTP or HTTPS URLs without embedded credentials are supported.": "자격 증명이 포함되지 않은 HTTP 또는 HTTPS URL만 지원됩니다.",
"Only PDF, Word (.docx), spreadsheet and image files can be shown": "PDF, Word (.docx), 스프레드시트, 이미지 파일만 표시할 수 있습니다",
"Only PNG, JPEG, GIF, WebP and SVG images can be shown": "PNG, JPEG, GIF, WebP, SVG 이미지만 표시할 수 있습니다",
"Only a worker can save its progress checkpoint.": "진행 체크포인트는 worker 자신만 저장할 수 있습니다.",
"Only iPhone Duo folds.": "iPhone Duo만 폴딩됩니다.",
"Only macOS VMs can be suspended. Stop a Linux VM instead; it boots in seconds.": "macOS VM만 일시 정지할 수 있습니다. 대신 Linux VM을 중지하세요. 몇 초 만에 시작됩니다.",
"Only regular text files can be previewed": "일반 텍스트 파일만 미리 볼 수 있습니다",
"Only simple object forms are supported": "단순 객체 형태의 폼만 지원됩니다",
"Only the main window can check agent updates.": "Agent 업데이트는 메인 창에서만 검사할 수 있습니다.",
