"Unsupported UI language.": "지원되지 않는 UI 언어입니다.",
"Unsupported native updater.": "지원되지 않는 네이티브 업데이터입니다.",
"Unsupported reasoning effort for this provider": "이 공급자는 이 추론 강도를 지원하지 않습니다",
"Usage estimates are available only in the main application window.": "사용량 추정은 메인 앱 창에서만 볼 수 있습니다.",
"Usage limits are available only in the main application window.": "사용량 한도는 메인 앱 창에서만 볼 수 있습니다.",
"Use a branch name with letters, numbers, hyphens, underscores, and slashes": "브랜치 이름은 문자, 숫자, 하이픈, 밑줄, 슬래시를 사용하세요",
