"Use a short stable checkpoint key.": "짧고 안정적인 체크포인트 키를 사용하세요.",
"Use a short stable message key.": "짧고 안정적인 메시지 키를 사용하세요.",
"Use an HTTP or HTTPS URL without embedded credentials.": "자격 증명이 포함되지 않은 HTTP 또는 HTTPS URL을 사용하세요.",
"Use an absolute executable path, or leave it empty for automatic discovery.": "절대 경로의 실행 파일을 사용하거나, 비워 두면 자동으로 찾습니다.",
"Use at most 24 file scopes.": "파일 범위는 최대 24개까지 사용할 수 있습니다.",
"Use either profileId or provider and model, not both.": "profileId 또는 공급자+모델 중 하나만 사용하세요.",
"Use relative file or directory scopes, not glob patterns.": "와일드카드 패턴이 아니라 상대 파일 또는 디렉터리 범위를 사용하세요.",
"Use the Codex harness for this command.": "이 명령에는 Codex Agent를 사용하세요.",
"Use the extension ID, such as dracula-theme.theme-dracula.": "dracula-theme.theme-dracula 같은 확장 ID를 사용하세요.",
"Use this on another task; the current task is already running this turn.": "다른 작업에 사용하세요. 현재 작업은 이미 이 턴을 실행 중입니다.",
"Use up to eight project rules.": "프로젝트 규칙은 최대 8개까지 사용할 수 있습니다.",
"VM names use lowercase letters, digits and dashes.": "VM 이름은 소문자, 숫자, 하이픈을 사용합니다.",
"VNC rejected the password.": "VNC가 비밀번호를 거부했습니다.",
"Wait for the Codex session to finish connecting.": "Codex 세션이 연결을 마치기를 기다리세요.",
"Wait for the Jev installation to finish before changing its settings.": "Jev 설정을 바꾸기 전에 설치가 끝나기를 기다리세요.",
"Wait for the Jev runtime installation to finish.": "Jev 런타임 설치가 끝나기를 기다리세요.",
"Wait for the agent to finish before merging its worktree.": "워크트리를 병합하기 전에 Agent가 끝나기를 기다리세요.",
"Wait for the agent to finish, or stop it first.": "Agent가 끝나기를 기다리거나 먼저 중지하세요.",
"Wait for this task's Jev browser test or assessment to finish before deleting it.": "삭제하기 전에 이 작업의 Jev 브라우저 테스트나 평가가 끝나기를 기다리세요.",
"Wait for this worker to settle before following up.": "후속 조치 전에 이 worker가 마무리되기를 기다리세요.",
"Wait for workers to stop before changing the team.": "팀을 바꾸기 전에 worker가 중지되기를 기다리세요.",
"Worker checkpoint limit reached.": "worker 체크포인트 한도에 도달했습니다.",
"Worker is no longer scheduled.": "worker가 더 이상 예약되지 않았습니다.",
"Worker profiles need unique IDs and an installed harness type.": "worker 프로필에는 고유한 ID와 설치된 Agent 유형이 필요합니다.",
"Worker unavailable": "worker를 사용할 수 없습니다",
"Worktree checkout is unavailable. Its Git metadata is missing.": "워크트리 체크아웃을 사용할 수 없습니다. Git 메타데이터가 없습니다.",
